---更新home数据
---@param activityDojo ActivityDojo
function JapaneseStoryMgr:UpdateHomeData(activityDojo)
    if not activityDojo then return end
    
    self:GetJapaneseStoryComponent():SetActivityDojo(activityDojo)
    GameUtils.Request(Interfaces.JapaneseStoryHome, {activityUuid = activityDojo.id}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            Events.Broadcast(Constants.EventNames.JapaneseStoryHomeDataUpdate)
            return
        end

        self:GetJapaneseStoryComponent():Initial(response.data)
        Events.Broadcast(Constants.EventNames.JapaneseStoryHomeDataUpdate)
    end)
end

---播放活动BGM
