    CriWareUtils.PlayMusicById(scheduleVo.bgm)
end

---停止bgm
function JapaneseStoryMgr:StopBGM()
    local scheduleVo = self:GetScheduleVo()
    CriWareUtils.StopById(scheduleVo.bgm)
end

---播放剧情
function JapaneseStoryMgr:PlayPlot(vo, endCb)
    if not vo then
        return
    end
    if self._isPlayPlot then
        return
    end
    self._isPlayPlot = true
    local plotIds = CfUtils.Split(vo.plotId)
    if not plotIds then
        GameUtils.Toast(localize("该关卡没有剧情参数"))
        self._isPlayPlot = false
        return
    end

    self:PlayingPlot(plotIds, endCb)
end

---剧情播放中
function JapaneseStoryMgr:PlayingPlot(plotIds, endCb)
    local co = cs_coroutine.start(function()
        for _, id in ipairs(plotIds) do
            local wait = true
            local plotGo = nil
            local lastDialog = UIModule.CurrentScreen:GetDialog(Constants.UITypeIds.JapaneseStoryEntryMain)
            ChapterUtils.ProcessChapter(checkNumber(id), function(go)
                if isNotNull(lastDialog) then
                    lastDialog.transform.localPosition = Vector3(9999, 9999, 9999)
                end
                URPCameraController:SetMainCameraActive(false)
                UINavigationBarRoot.Instance:SetActive(false)
                plotGo = go
            end, function()
                --所有的播完结束
                if isNotNull(lastDialog) then
                    lastDialog.transform.localPosition = Vector3(0, 0, 0)
                end
                URPCameraController:SetMainCameraActive(true)
                UINavigationBarRoot.Instance:SetActive(true)
                wait = false
            end)

            while wait do
                coroutine.yield()
            end

            KTool.SafeDelete(plotGo)

            --dispose
            coroutine.yield()
        end

        self:PlayBGM()
        if endCb then
            endCb()
        end
    end)
end

---IsActive @ 判断活动是否开启
function JapaneseStoryMgr:IsActive()
    local activityDojo = self:GetActivityDojo()
    if isNull(activityDojo) then
        return false
    end
    local startTime = checkNumber(activityDojo.startTime)
    local endTime = checkNumber(activityDojo.endTime)
    ---@type PlayerComponent
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local curTime = comp:GetPlayerDojo():GetServerTimeWithTimeZone()
    return curTime >= startTime and curTime <= endTime
end

function JapaneseStoryMgr:IsClose()
    local activityDojo = self:GetActivityDojo()
    if isNull(activityDojo) then
        return false
    end
    local startTime = checkNumber(activityDojo.startTime)
    local closeTime = checkNumber(activityDojo.closeTime)
    ---@type PlayerComponent
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local curTime = comp:GetPlayerDojo():GetServerTimeWithTimeZone()
    return curTime >= startTime and curTime <= closeTime
end

---检查活动是否开启
function JapaneseStoryMgr:CheckActive()
    local active = self:IsActive()
    if not active then
        GameUtils.Toast(localize("活动已结束"))
    end

    return active
end

function JapaneseStoryMgr:CheckClose()
    local active = self:IsClose()
    if not active then
        GameUtils.Toast(localize("活动已结束"))
    end

    return active
end

