---检查节点是否达到开启时间
function JapaneseStoryMgr:CheckChapterOpenTime(unlockCountdown)
    local second = checkInt(unlockCountdown) + GameUtils.GetServerTime() - self:GetEnterTimestamp()
    return second <= 0
end

---检查入口按钮是否解锁
---@param btnType JapaneseStoryConstants.EntryBtnType
function JapaneseStoryMgr:CheckEntryBtnUnlock(btnType)
    local conf = self:GetEntryBtnConf(btnType) or {}
    if checkInt(conf.unlockLevel) == 0 then return true end

    local mainQuestId = self:GetMainQuestId()
    return mainQuestId >= checkInt(conf.unlockLevel)
end

