---更新MainQuestMap
function JapaneseStoryMgr:UpdateMainQuestMap()
    local questId = self:GetMainQuestId()
    local questMap = self:GetMainQuestMap()
    local questVo = self:GetQuestVo()
    for i, v in ipairs(questMap) do
        if checkInt(v.status) == 1 then -- 未通关
            local allStageData =questVo[tostring(v.questId)]
            local allClear = true
            for _, questData in ipairs(allStageData) do
                if questId < questData.id then
                    allClear = false
                    break
                end
            end
            if allClear then
                questMap[i].status = 2
                if questMap[i + 1] then
                    questMap[i + 1].status = 1
                end
            end
        end 
    end
end

