---获取主线关卡表数据
function JapaneseStoryMgr:GetQuestVo()
    local vo = CfUtils.GetCf(AutoIds.IdSetting6495, 'JapaneseStoryQuestVo', true)
    local contentId = self:GetActivityContentId()
    local questData = {}
    for i, v in ipairs(vo) do
        if contentId == checkInt(v.activityId) then
            if questData[tostring(v.placeId)] then
                table.insert(questData[tostring(v.placeId)], v)
            else
                questData[tostring(v.placeId)] = {v}
            end
        end
    end

    for k, v in pairs(questData) do
        table.sort(v, function(a, b)
            return checkInt(a.id) < checkInt(b.id)
        end)
    end
    return questData
end

