---获取最新关卡
---@return integer, integer @章节id, 关卡id
function JapaneseStoryMgr:GetNewQuest()
    local mainQuestId = self:GetMainQuestId()
    
    local data = self:GetQuestVo()
    local chapterId = nil
    local stageId = nil

    if checkInt(mainQuestId) == 0 then
        return 
    end
    
    for id, v in pairs(data) do
        chapterId = id
        for _, vo in ipairs(v) do
            if checkInt(vo.unlockLevel) == mainQuestId then
                return id, vo.id
            end
            stageId = v.id
        end
    end

    for id, v in pairs(data) do
        chapterId = id
        for _, vo in ipairs(v) do
            if checkInt(vo.id) == mainQuestId then
                return id, vo.id
            end
            stageId = v.id
        end
    end
    
    return chapterId, stageId
end

