---获取地图红点状态
function JapaneseStoryMgr:GetMapRedPointState()
    local id = self:GetMainQuestId()
    local mapQuest = self:GetMainQuestMap()
    local conf = CfUtils.GetCf(AutoIds.IdSetting6494, "JapaneseStoryPlotVo", true)
    if id == 0 then return true end
    --
    local data = nil
    for _, v in ipairs(conf) do
        if checkInt(v.unlockLevel) == checkInt(id) then
            data = v
            break
        end
    end
    if not data and id > 0 then return false end

    local placeId = checkInt(data.placeId)
    local mapQuestData = nil
    for i, v in ipairs(mapQuest) do
        if v.questId == placeId then
            mapQuestData = v
            break
        end
    end
    return self:CheckChapterOpenTime(mapQuestData.unlockCountdown)
end

